package main

import (
	"context"
	"fmt"
	"math/rand/v2"
	"net/http"
	"net/http/httptest"
	"strconv"
	"sync/atomic"
	"time"
)

// get retries 429 and 503 within ctx's deadline. Example 2 parses Retry-After fully.
func get(ctx context.Context, c *http.Client, r *rand.Rand, url string) error {
	for attempt := range 4 {
		req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
		if err != nil {
			return err
		}
		resp, err := c.Do(req)
		if err != nil {
			return err
		}
		resp.Body.Close()
		if resp.StatusCode != http.StatusTooManyRequests &&
			resp.StatusCode != http.StatusServiceUnavailable {
			return nil
		}
		wait := r.N(min(100*time.Millisecond<<attempt, 2*time.Second)) // full jitter
		if secs, err := strconv.Atoi(resp.Header.Get("Retry-After")); err == nil && secs >= 0 {
			wait = time.Duration(secs) * time.Second // the server's hint wins
		}
		if deadline, ok := ctx.Deadline(); ok && time.Until(deadline) < wait {
			return fmt.Errorf("%d: server asks for %v, more than our budget", resp.StatusCode, wait)
		}
		fmt.Printf("%d, waiting %v\n", resp.StatusCode, wait.Round(time.Millisecond))
		select {
		case <-time.After(wait):
		case <-ctx.Done():
			return ctx.Err()
		}
	}
	return fmt.Errorf("giving up after 4 attempts")
}

func main() {
	var calls atomic.Int32
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		switch calls.Add(1) {
		case 1: // no hint: we back off on our own
		case 2:
			w.Header().Set("Retry-After", "1")
		default:
			w.Header().Set("Retry-After", "3600") // come back in an hour
		}
		w.WriteHeader(http.StatusTooManyRequests)
	}))
	defer srv.Close()

	ctx, cancel := context.WithTimeout(context.Background(), 8*time.Second)
	defer cancel()
	r := rand.New(rand.NewPCG(1, 2))
	fmt.Println("err:", get(ctx, &http.Client{Timeout: 5 * time.Second}, r, srv.URL))
}

files.examples/04_idempotency_key.go:
package main

import (
	"bytes"
	"context"
	"crypto/rand"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"sync"
	"time"
)

// payments charges once per Idempotency-Key and replays the stored result
// for every repeat. The first response it sends is lost on the way back.
type payments struct {
	mu      sync.Mutex
	byKey   map[string]string // key -> payment id
	charges int
	calls   int
}

func (p *payments) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	p.mu.Lock()
	defer p.mu.Unlock()
	p.calls++
	key := r.Header.Get("Idempotency-Key")
	id, seen := p.byKey[key]
	if key == "" || !seen {
		p.charges++ // in real life: one database transaction
		id = fmt.Sprintf("pay_%d", p.charges)
		p.byKey[key] = id
	}
	if p.calls == 1 {
		panic(http.ErrAbortHandler) // committed, but the connection dies before the answer
	}
	w.WriteHeader(http.StatusCreated)
	io.WriteString(w, id)
}

// post sends one attempt of the payment.
func post(ctx context.Context, c *http.Client, url, key string) (string, error) {
	body := bytes.NewReader([]byte(`{"amount_kurus":125000,"currency":"TRY"}`))
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, url, body)
	if err != nil {
		return "", err
	}
	if key != "" {
		req.Header.Set("Idempotency-Key", key)
	}
	resp, err := c.Do(req)
	if err != nil {
		return "", err
	}
	defer resp.Body.Close()
	id, err := io.ReadAll(resp.Body)
	return string(id), err
}

func main() {
	ctx, client := context.Background(), &http.Client{Timeout: 5 * time.Second}
	for _, key := range []string{"", rand.Text()} {
		fmt.Printf("with Idempotency-Key: %t\n", key != "")
		p := &payments{byKey: map[string]string{}}
		srv := httptest.NewServer(p)
		id, err := post(ctx, client, srv.URL, key)
		if err != nil {
			fmt.Println("  no response: charged or not? unknown, so retry")
			id, err = post(ctx, client, srv.URL, key) // the same key: same operation
		}
		srv.Close()
		fmt.Printf("  got %s (err=%v); customer charged %d time(s)\n", id, err, p.charges)
	}
}
